export type ImageKey = keyof typeof images;

/** Largest encoded rendition — use as the plain `src` fallback. */
export function imageSrc(key: ImageKey): string {
  const s = images[key].sources;
  return s[s.length - 1]?.src ?? "";
}

/** `srcset` string covering every encoded width. */
export function imageSrcSet(key: ImageKey): string {
  return images[key].sources.map((s) => `${s.src} ${s.w}w`).join(", ");
}
